<script>
(function () {
  const entry = document.getElementById('entry');
  const expressions = document.getElementById('expressions');
  const liveResult = document.getElementById('liveResult');
  const clearButton = document.getElementById('clearButton');
  let rows = [];
  let previousAnswer = '';

  function evaluateExpression(raw) {
    if (!raw.trim()) return null;
    let s = raw.replace(/×/g, '*').replace(/÷/g, '/').replace(/−/g, '-');
    s = s.replace(/√\s*([0-9.]+)/g, 'Math.sqrt($1)');
    s = s.replace(/∛\s*([0-9.]+)/g, 'Math.cbrt($1)');
    s = s.replace(/\|([^|]*)\|/g, 'Math.abs($1)');
    s = s.replace(/\bans\b/g, previousAnswer || '0');
    s = s.replace(/\^/g, '**').replace(/(\d+(?:\.\d+)?)%/g, '($1/100)');
    s = s.replace(/\b(sin|cos|tan)\(/g, 'Math.$1(');
    if (!/^[0-9+\-*/().,\sA-Za-z]*$/.test(s)) return null;
    try {
      const value = Function('"use strict"; return (' + s + ')')();
      if (typeof value !== 'number' || !Number.isFinite(value)) return null;
      return Number.isInteger(value) ? String(value) : String(Number(value.toPrecision(10)));
    } catch (e) {
      return null;
    }
  }

  function formatExpression(raw) {
    let s = raw.trim();
    if (!s) return '';
    const fraction = s.match(/^(.+?)\/(.+)$/);
    if (fraction && !fraction[1].includes('/')) {
      return '<span class="frac"><span>' + formatExpression(fraction[1]) +
        '</span><span class="den">' + formatExpression(fraction[2]) + '</span></span>';
    }
    s = s.replace(/√\s*([0-9.]+)/g, '<span class="root">√</span><span>$1</span>');
    s = s.replace(/∛\s*([0-9.]+)/g, '<span class="root">∛</span><span>$1</span>');
    s = s.replace(/\|([^|]*)\|/g, '<span class="abs">|$1|</span>');
    s = s.replace(/\^([0-9]+)/g, '<sup>$1</sup>');
    s = s.replace(/\*/g, ' × ').replace(/\//g, ' ÷ ').replace(/-/g, '−');
    return s;
  }

  function updateLive() {
    const result = evaluateExpression(entry.value);
    liveResult.textContent = result === null ? '' : '= ' + result;
    clearButton.textContent = rows.length ? (entry.value ? 'clear' : 'clear all') : 'clear all';
  }

  function focusEntry() {
    entry.focus();
    const end = entry.value.length;
    entry.setSelectionRange(end, end);
  }

  function insertText(text) {
    const start = entry.selectionStart == null ? entry.value.length : entry.selectionStart;
    const end = entry.selectionEnd == null ? entry.value.length : entry.selectionEnd;
    entry.value = entry.value.slice(0, start) + text + entry.value.slice(end);
    const pos = start + text.length;
    entry.focus();
    entry.setSelectionRange(pos, pos);
    updateLive();
  }

  function submit() {
    const raw = entry.value.trim();
    const value = evaluateExpression(raw);
    if (!raw || value === null) return;
    rows.push({ expression: raw, result: value });
    previousAnswer = value;
    entry.value = '';
    renderRows();
    focusEntry();
  }

  function renderRows() {
    expressions.innerHTML = '';
    rows.forEach(function (row) {
      const el = document.createElement('div');
      el.className = 'expression-row';
      el.innerHTML = '<span class="math-expression">' + formatExpression(row.expression) +
        '</span><span class="result">= ' + row.result + '</span>';
      expressions.appendChild(el);
    });
    const active = document.createElement('div');
    active.className = 'expression-row active';
    active.innerHTML = '<input id="entry" type="text" autocomplete="off" spellcheck="false" aria-label="Calculator expression"><span class="result" id="liveResult"></span>';
    expressions.appendChild(active);
    const oldValue = entry.value;
    entry = document.getElementById('entry');
    entry.value = oldValue;
    liveResult = document.getElementById('liveResult');
    entry.addEventListener('input', updateLive);
    entry.addEventListener('keydown', onKeyDown);
    updateLive();
  }

  function onKeyDown(event) {
    if (event.key === 'Enter') {
      event.preventDefault();
      submit();
    } else if (event.key === 'Escape') {
      entry.value = '';
      updateLive();
    }
  }

  entry.addEventListener('input', updateLive);
  entry.addEventListener('keydown', onKeyDown);

  document.querySelectorAll('[data-insert]').forEach(function (button) {
    button.addEventListener('click', function () {
      insertText(button.getAttribute('data-insert'));
    });
  });
  document.querySelectorAll('[data-action]').forEach(function (button) {
    button.addEventListener('click', function () {
      const action = button.getAttribute('data-action');
      if (action === 'enter') submit();
      if (action === 'backspace') {
        const start = entry.selectionStart, end = entry.selectionEnd;
        if (start === end && start > 0) {
          entry.value = entry.value.slice(0, start - 1) + entry.value.slice(end);
          entry.setSelectionRange(start - 1, start - 1);
        } else {
          entry.value = entry.value.slice(0, start) + entry.value.slice(end);
          entry.setSelectionRange(start, start);
        }
        updateLive();
        focusEntry();
      }
      if (action === 'left' || action === 'right') {
        const pos = entry.selectionStart || 0;
        const next = action === 'left' ? Math.max(0, pos - 1) : Math.min(entry.value.length, pos + 1);
        entry.setSelectionRange(next, next);
        focusEntry();
      }
    });
  });
  clearButton.addEventListener('click', function () {
    if (entry.value) {
      entry.value = '';
    } else {
      rows = [];
      previousAnswer = '';
      renderRows();
    }
    updateLive();
    focusEntry();
  });
  document.querySelectorAll('.tool-tab').forEach(function (tab) {
    tab.addEventListener('click', function () {
      document.querySelectorAll('.tool-tab').forEach(function (t) { t.classList.remove('selected'); });
      tab.classList.add('selected');
    });
  });
  document.querySelectorAll('.angle-switch button').forEach(function (button) {
    button.addEventListener('click', function () {
      document.querySelectorAll('.angle-switch button').forEach(function (b) { b.classList.remove('on'); });
      button.classList.add('on');
    });
  });
  updateLive();
})();
</script>
